const STORAGE_KEY = "jobCriteriaCardV01";
const choices = [
  {value:"must", label:"반드시 필요", description:"이 조건이 없으면 지원하기 어렵다."},
  {value:"nice", label:"있으면 좋음", description:"중요하지만 다른 장점이 있다면 조정 가능하다."},
  {value:"low", label:"중요하지 않음", description:"직업선택에 큰 영향을 주지 않는다."}
];
const reclassificationChoices = [
  {value:"must",label:"반드시 필요 유지",description:"이 조건이 없으면 여전히 지원하기 어렵습니다."},
  {value:"nice",label:"있으면 좋음으로 변경",description:"중요하지만 다른 장점이 있다면 조정할 수 있습니다."},
  {value:"low",label:"중요하지 않음으로 변경",description:"생각해 보니 직업선택에 큰 영향을 주는 조건은 아닙니다."}
];
let state = createEmptyState();

function createEmptyState() { return {screen:"start",clientInfo:{},currentIndex:0,answers:{},deepIndex:0,deepCardIds:[],finalMustCardIds:[],deepResponses:{},postDeepMustCards:[],quickReviewResults:{},pairwiseComparisons:[],comparisonWins:{},comparisonCount:{},comparisonIndex:0,absoluteCandidates:[],absoluteConfirmResults:{},absoluteConditions:[],importantConditions:[],preferredConditions:[],unimportantConditions:[],finalClassifications:{},criteriaHistory:{},coreSelectionMode:"",coreSelections:[],realityIndex:0,realityTargetIds:[],realityAssessments:{},realityGapSignals:[],rigiditySignals:[],sourceConcentrationSignals:[],cardCombinationSignals:[],counselingSignals:[],recommendedQuestions:[],counselorQuestionNotes:{},generatedCareerStatement:"",clientApprovedCareerStatement:"",careerStatementValidation:"",wdepOriginalAbsoluteConditions:[],wdep:{wantConfirmed:"",doingActivities:[],doingOther:"",doingNote:"",evaluation:"",improvementAreas:[]},maintainedConditions:[],adjustableConditions:[],competenciesToDevelop:[],actionPlan:{actionType:"",what:"",amount:"",deadline:"",generatedSentence:"",feasibility:"",confirmed:false},confirmedActionPlan:"",nextCheckPoint:"",counselingCompleted:false,consultationCompleted:false,consultationCompletedAt:""}; }
function validateData() {
  const expected={A:24,B:6,C:6,D:6,E:12,F:6};
  if(!Array.isArray(JOB_CARDS)||JOB_CARDS.length!==60) throw new Error("카드 수가 60개가 아닙니다.");
  const ids=new Set(JOB_CARDS.map(card=>card.id));
  if(ids.size!==60) throw new Error("중복된 카드 ID가 있습니다.");
  Object.entries(expected).forEach(([letter,count])=>{
    for(let number=1;number<=count;number++) if(!ids.has(letter+String(number).padStart(2,"0"))) throw new Error(`${letter}${String(number).padStart(2,"0")} 카드가 없습니다.`);
    if(JOB_CARDS.filter(card=>card.id.startsWith(letter)).length!==count) throw new Error(`${letter} 영역 카드 수가 올바르지 않습니다.`);
  });
  JOB_CARDS.forEach(card=>{const data=counselingData[card.id];if(!data||data.questions.length!==2||!data.counselorTags.length) throw new Error(`${card.id} 상담 데이터가 올바르지 않습니다.`);});
  if(Object.keys(counselingData).length!==60||counselingSources.length!==7) throw new Error("심층상담 데이터 수가 올바르지 않습니다.");
}
function saveState(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}
function loadState(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));if(saved&&saved.clientInfo&&saved.answers&&Number.isInteger(saved.currentIndex)){const empty=createEmptyState();state={...empty,...saved};state.wdep={...empty.wdep,...(saved.wdep||{})};state.actionPlan={...empty.actionPlan,...(saved.actionPlan||{})};state.deepResponses=saved.deepResponses||{};state.deepCardIds=Array.isArray(saved.deepCardIds)?saved.deepCardIds:[];state.finalMustCardIds=Array.isArray(saved.finalMustCardIds)?saved.finalMustCardIds:[];}}catch(error){localStorage.removeItem(STORAGE_KEY);}}
function showScreen(name){["start","card","result","deep-intro","deep","deep-result","core-select","pairwise","pairwise-result","absolute-confirm","important","final","reality-intro","reality","reality-result","reality-complete","statement","wdep","counseling-summary","final-result"].forEach(item=>document.getElementById(`${item}-screen`).hidden=item!==name);if(name==="deep-result")updateCoreStartPanel();state.screen=name;saveState();window.scrollTo(0,0);}
function getMustCards(){return JOB_CARDS.filter(card=>state.answers[card.id]==="must");}
function getDeepCards(){return state.deepCardIds.map(id=>JOB_CARDS.find(card=>card.id===id)).filter(Boolean);}
function escapeHtml(value){return String(value||"").replace(/[&<>"]/g,character=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[character]));}

function updateDesiredJobInput(){const visible=["희망직무가 있다","몇 가지 직무를 고민하고 있다"].includes(document.getElementById("desired-job-status").value);document.getElementById("desired-job-wrap").hidden=!visible;document.getElementById("desired-job-name").required=visible;}
function fillStartForm(){const info=state.clientInfo;document.getElementById("client-name").value=info.clientName||"";document.getElementById("current-status").value=info.currentStatus||"";document.getElementById("desired-job-status").value=info.desiredJobStatus||"";document.getElementById("desired-job-name").value=info.desiredJobName||"";document.getElementById("main-concern").value=info.mainConcern||"";updateDesiredJobInput();}
function renderChoiceButtons(selectedValue){const container=document.getElementById("choice-buttons");container.innerHTML="";choices.forEach(choice=>{const button=document.createElement("button");button.type="button";button.className="choice-button"+(selectedValue===choice.value?" selected":"");button.dataset.value=choice.value;button.setAttribute("aria-pressed",selectedValue===choice.value);button.innerHTML=`<strong>${choice.label}</strong><span>${choice.description}</span>`;button.addEventListener("click",()=>selectChoice(choice.value));container.appendChild(button);});}
function renderCard(){state.currentIndex=Math.max(0,Math.min(state.currentIndex,JOB_CARDS.length-1));const card=JOB_CARDS[state.currentIndex],position=state.currentIndex+1;document.getElementById("progress-text").textContent=`${position} / ${JOB_CARDS.length}`;document.getElementById("progress-bar").style.width=`${position/JOB_CARDS.length*100}%`;document.querySelector("#card-screen .progress-track").setAttribute("aria-valuenow",position);document.getElementById("card-category").textContent=card.category;document.getElementById("card-id").textContent=card.id;document.getElementById("card-front").textContent=card.front;document.getElementById("card-back").textContent=card.back;document.getElementById("previous-button").disabled=state.currentIndex===0;renderChoiceButtons(state.answers[card.id]);saveState();}
function selectChoice(value){state.answers[JOB_CARDS[state.currentIndex].id]=value;saveState();if(state.currentIndex<JOB_CARDS.length-1){state.currentIndex++;renderCard();}else if(JOB_CARDS.every(card=>state.answers[card.id]))renderResults();}
function renderResults(){if(!JOB_CARDS.every(card=>state.answers[card.id])){showScreen("card");renderCard();return;}const counts={must:0,nice:0,low:0};JOB_CARDS.forEach(card=>counts[state.answers[card.id]]++);if(counts.must+counts.nice+counts.low!==60)throw new Error("결과 합계가 60이 아닙니다.");document.getElementById("result-counts").innerHTML=choices.map(choice=>`<div class="count-item">${choice.label}<strong>${counts[choice.value]}개</strong></div>`).join("");document.getElementById("many-must-message").hidden=counts.must<5;const hasDeepSession=state.deepCardIds.length>0;document.getElementById("no-must-message").hidden=counts.must>0;document.getElementById("deep-intro-button").disabled=counts.must===0&&!hasDeepSession;document.getElementById("result-lists").innerHTML=choices.map(choice=>{const cards=JOB_CARDS.filter(card=>state.answers[card.id]===choice.value);return `<section class="result-group"><h2>${choice.label} <span class="card-small-id">${cards.length}개</span></h2><ul>${cards.map(card=>`<li>${card.front}<span class="card-small-id">${card.id}</span></li>`).join("")||"<li>선택된 카드가 없습니다.</li>"}</ul></section>`;}).join("");showScreen("result");}

function renderDeepIntro(){const deepCards=getDeepCards(),mustCards=getMustCards(),cards=deepCards.length?deepCards:mustCards;if(!cards.length){renderResults();return;}document.getElementById("deep-intro-count").textContent=`${cards.length}개`;showScreen("deep-intro");}
function getDeepResponse(card){if(!state.deepResponses[card.id])state.deepResponses[card.id]={question1Answer:"",question2Answer:"",selectedSources:[],counselorTags:[...counselingData[card.id].counselorTags],initialClassification:"must",finalClassification:"must",reclassificationNote:""};const response=state.deepResponses[card.id];response.initialClassification=response.initialClassification||"must";response.finalClassification=response.finalClassification||state.answers[card.id]||"must";response.reclassificationNote=response.reclassificationNote||"";return response;}
function updateFinalMustIds(){state.finalMustCardIds=getDeepCards().filter(card=>getDeepResponse(card).finalClassification==="must").map(card=>card.id);}
function saveDeepInput(cardId){const response=state.deepResponses[cardId];response.question1Answer=document.getElementById("deep-answer-1").value;response.question2Answer=document.getElementById("deep-answer-2").value;response.selectedSources=[...document.querySelectorAll('#source-options input:checked')].map(input=>input.value);response.reclassificationNote=document.getElementById("reclassification-note").value;response.counselorTags=[...counselingData[cardId].counselorTags];updateFinalMustIds();saveState();}
function renderReclassificationButtons(card,response){const container=document.getElementById("reclassification-options");container.innerHTML="";reclassificationChoices.forEach(choice=>{const button=document.createElement("button");button.type="button";button.className="choice-button"+(response.finalClassification===choice.value?" selected":"");button.dataset.value=choice.value;button.setAttribute("aria-pressed",response.finalClassification===choice.value);button.innerHTML=`<strong>${choice.label}</strong><span>${choice.description}</span>`;button.addEventListener("click",()=>{saveDeepInput(card.id);response.finalClassification=choice.value;state.answers[card.id]=choice.value;updateFinalMustIds();saveState();renderReclassificationButtons(card,response);});container.appendChild(button);});}
function renderDeepCard(){const deepCards=getDeepCards();if(!deepCards.length){renderResults();return;}state.deepIndex=Math.max(0,Math.min(state.deepIndex,deepCards.length-1));const card=deepCards[state.deepIndex],data=counselingData[card.id],response=getDeepResponse(card),position=state.deepIndex+1;document.getElementById("deep-progress-text").textContent=`핵심조건 탐색 ${position} / ${deepCards.length}`;document.getElementById("deep-progress-bar").style.width=`${position/deepCards.length*100}%`;const track=document.querySelector("#deep-screen .progress-track");track.setAttribute("aria-valuemax",deepCards.length);track.setAttribute("aria-valuenow",position);document.getElementById("deep-card-category").textContent=card.category;document.getElementById("deep-card-id").textContent=card.id;document.getElementById("deep-card-front").textContent=card.front;document.getElementById("deep-card-back").textContent=card.back;document.getElementById("deep-questions").innerHTML=data.questions.map((question,index)=>`<div class="deep-question"><label for="deep-answer-${index+1}">${index+1}. ${question}</label><textarea id="deep-answer-${index+1}" placeholder="대화 내용을 자유롭게 기록해 주세요.">${escapeHtml(response[`question${index+1}Answer`])}</textarea></div>`).join("");document.getElementById("source-options").innerHTML=counselingSources.map(source=>`<label class="source-option"><input type="checkbox" value="${source.id}" ${response.selectedSources.includes(source.id)?"checked":""}> <span>${source.id} ${source.label}</span></label>`).join("");document.getElementById("reclassification-note").value=response.reclassificationNote;renderReclassificationButtons(card,response);document.getElementById("counselor-tags").textContent=data.counselorTags.join(" · ");document.getElementById("deep-previous-button").disabled=state.deepIndex===0;document.getElementById("deep-next-button").textContent=position===deepCards.length?"심층탐색 완료":"다음 조건";document.querySelectorAll("#deep-questions textarea, #source-options input, #reclassification-note").forEach(input=>input.addEventListener("input",()=>saveDeepInput(card.id)));showScreen("deep");}
function moveDeepNext(){const deepCards=getDeepCards(),card=deepCards[state.deepIndex];saveDeepInput(card.id);if(state.deepIndex<deepCards.length-1){state.deepIndex++;renderDeepCard();}else renderDeepResults();}
function renderDeepResults(){const deepCards=getDeepCards();if(!deepCards.length){renderResults();return;}updateFinalMustIds();const totals={must:0,nice:0,low:0};deepCards.forEach(card=>totals[getDeepResponse(card).finalClassification]++);document.getElementById("deep-result-summary").textContent=`처음 반드시 필요로 선택한 ${deepCards.length}개의 조건을 살펴보았습니다.`;document.getElementById("deep-result-counts").innerHTML=`<div class="count-item">처음 반드시 필요<strong>${deepCards.length}개</strong></div>${reclassificationChoices.map(choice=>`<div class="count-item">${choice.value==="must"?"심층탐색 후 반드시 필요 유지":choice.label}<strong>${totals[choice.value]}개</strong></div>`).join("")}`;document.getElementById("deep-result-list").innerHTML=deepCards.map(card=>{const response=getDeepResponse(card),sourceLabels=response.selectedSources.map(id=>counselingSources.find(source=>source.id===id)?.label).filter(Boolean),questions=counselingData[card.id].questions,status=reclassificationChoices.find(choice=>choice.value===response.finalClassification).label;return `<section class="result-group deep-result-card"><h2>${card.front} <span class="card-small-id">${card.id}</span></h2><span class="classification-status">최종분류: ${status}</span><p class="source-summary"><strong>기준출처:</strong> ${sourceLabels.length?sourceLabels.join(" · "):"선택하지 않음"}</p>${response.reclassificationNote?`<p class="change-note"><strong>변경 메모:</strong> ${escapeHtml(response.reclassificationNote)}</p>`:""}<details><summary>답변 보기</summary><p class="answer-block"><strong>${escapeHtml(questions[0])}</strong>${escapeHtml(response.question1Answer)||"입력된 답변이 없습니다."}</p><p class="answer-block"><strong>${escapeHtml(questions[1])}</strong>${escapeHtml(response.question2Answer)||"입력된 답변이 없습니다."}</p></details></section>`;}).join("");showScreen("deep-result");}

function cardById(id){return JOB_CARDS.find(card=>card.id===id);}
function updateCoreStartPanel(){updateFinalMustIds();const count=state.finalMustCardIds.length,guidance=document.getElementById("core-start-guidance"),button=document.getElementById("core-start-button");if(count===0){guidance.innerHTML="심층탐색 후 반드시 필요로 남은 조건은 없습니다.<br>이는 문제가 있는 결과가 아니라, 처음 생각했던 기준을 상담과정에서 다시 정리한 결과입니다.";button.textContent="중요조건 정하기";}else{guidance.textContent="이제 심층탐색 후에도 반드시 필요하다고 남은 조건을 중심으로 핵심 직업기준을 정합니다.";button.textContent="핵심 직업기준 정하기";}}
function deepReferenceHtml(card){const response=state.deepResponses[card.id];if(!response)return "";const sources=(response.selectedSources||[]).map(id=>counselingSources.find(source=>source.id===id)?.label).filter(Boolean).join(" · ")||"선택하지 않음";return `<details><summary>심층답변 보기</summary><p class="answer-block"><strong>질문 1 답변</strong>${escapeHtml(response.question1Answer)||"입력된 답변이 없습니다."}</p><p class="answer-block"><strong>질문 2 답변</strong>${escapeHtml(response.question2Answer)||"입력된 답변이 없습니다."}</p><p><strong>기준출처:</strong> ${sources}</p>${response.reclassificationNote?`<p><strong>재분류 메모:</strong> ${escapeHtml(response.reclassificationNote)}</p>`:""}</details>`;}
function resetCoreFlow(){state.postDeepMustCards=[...state.finalMustCardIds];state.quickReviewResults={};state.pairwiseComparisons=[];state.comparisonWins={};state.comparisonCount={};state.comparisonIndex=0;state.absoluteCandidates=[];state.absoluteConfirmResults={};state.absoluteConditions=[];state.importantConditions=[];state.preferredConditions=[];state.unimportantConditions=[];state.finalClassifications={};state.criteriaHistory={};state.coreSelections=[];}
function startCoreSelection(){updateFinalMustIds();resetCoreFlow();const count=state.postDeepMustCards.length;if(count===0){renderImportantSelection();return;}if(count<=3){state.absoluteCandidates=[...state.postDeepMustCards];renderAbsoluteConfirm();return;}state.coreSelectionMode=count===4?"direct":"quick";state.coreSelections=count===4?[]:[...state.postDeepMustCards];state.postDeepMustCards.forEach(id=>state.quickReviewResults[id]="must");renderCoreSelect();}
function renderCoreSelect(){const ids=state.postDeepMustCards,mode=state.coreSelectionMode,direct=mode==="direct";document.getElementById("core-select-title").textContent=direct?"특히 지키고 싶은 조건 선택":"반드시 필요 조건 빠른 재검토";document.getElementById("core-select-guidance").innerHTML=direct?`<p>심층탐색 후에도 반드시 필요하다고 남은 조건이 4개입니다.</p><p>이 가운데 다른 조건을 포기하더라도 특히 지키고 싶은 조건을 최대 3개 선택해 주세요.</p>`:`<p>심층탐색 후에도 반드시 필요하다고 남은 조건이 여러 개 있습니다.</p><p>모두 중요한 조건이지만 실제 직업선택에서는 모든 조건을 동시에 충족하기 어려울 수 있습니다.</p><p>심층탐색까지 마친 지금, 다른 장점이 충분하다면 조정할 수 있는 조건이 있나요?</p>`;document.getElementById("core-select-list").innerHTML=ids.map(id=>{const card=cardById(id),selected=direct?state.coreSelections.includes(id):state.quickReviewResults[id]==="must";return `<article class="selection-card ${selected?"selected":""}" data-id="${id}"><h2>${card.front} <span class="card-small-id">${id}</span></h2><p>${card.back}</p>${direct?`<button class="secondary-button core-toggle" type="button">${selected?"선택됨":"선택"}</button>`:`<div class="decision-buttons"><button type="button" data-value="must" class="${selected?"selected":""}">절대 유지</button><button type="button" data-value="nice" class="${!selected?"selected":""}">중요조건으로 조정</button></div>`}${deepReferenceHtml(card)}</article>`;}).join("");const kept=direct?state.coreSelections.length:Object.values(state.quickReviewResults).filter(value=>value==="must").length;document.getElementById("core-selection-count").textContent=direct?`${kept} / 3 선택`:`절대 유지 ${kept}개`;document.querySelectorAll("#core-select-list .selection-card").forEach(element=>{const id=element.dataset.id;if(direct)element.querySelector(".core-toggle").addEventListener("click",()=>{const index=state.coreSelections.indexOf(id);if(index>=0)state.coreSelections.splice(index,1);else if(state.coreSelections.length<3)state.coreSelections.push(id);renderCoreSelect();});else element.querySelectorAll(".decision-buttons button").forEach(button=>button.addEventListener("click",()=>{state.quickReviewResults[id]=button.dataset.value;renderCoreSelect();}));});showScreen("core-select");}
function continueCoreSelect(){if(state.coreSelectionMode==="direct"){state.absoluteCandidates=[...state.coreSelections];state.postDeepMustCards.forEach(id=>{if(!state.absoluteCandidates.includes(id))state.quickReviewResults[id]="nice";});renderAbsoluteConfirm();return;}const kept=state.postDeepMustCards.filter(id=>state.quickReviewResults[id]==="must");if(kept.length<=3){state.absoluteCandidates=kept;renderAbsoluteConfirm();}else{state.coreSelections=[];createPairwiseComparisons(kept);renderPairwise();}}
function createPairwiseComparisons(ids){state.pairwiseComparisons=ids.map((id,index)=>[id,ids[(index+1)%ids.length]]);state.comparisonWins=Object.fromEntries(ids.map(id=>[id,0]));state.comparisonCount=Object.fromEntries(ids.map(id=>[id,0]));state.comparisonIndex=0;saveState();}
function renderPairwise(){if(state.comparisonIndex>=state.pairwiseComparisons.length){renderPairwiseResults();return;}const pair=state.pairwiseComparisons[state.comparisonIndex],cards=pair.map(cardById),position=state.comparisonIndex+1,total=state.pairwiseComparisons.length;document.getElementById("pairwise-progress").textContent=`${position} / ${total}`;document.getElementById("pairwise-progress-bar").style.width=`${position/total*100}%`;document.getElementById("pairwise-options").innerHTML=`<button class="pairwise-choice" data-id="${cards[0].id}">${cards[0].front}</button><span class="pairwise-vs">VS</span><button class="pairwise-choice" data-id="${cards[1].id}">${cards[1].front}</button>`;document.querySelectorAll(".pairwise-choice").forEach(button=>button.addEventListener("click",()=>{const winner=button.dataset.id;state.comparisonWins[winner]++;pair.forEach(id=>state.comparisonCount[id]++);state.comparisonIndex++;saveState();renderPairwise();}));showScreen("pairwise");}
function renderPairwiseResults(){const ids=Object.keys(state.comparisonWins).sort((a,b)=>state.comparisonWins[b]-state.comparisonWins[a]||a.localeCompare(b));if(!state.coreSelections.length)state.coreSelections=ids.slice(0,3);document.getElementById("pairwise-result-list").innerHTML=ids.map(id=>{const card=cardById(id),selected=state.coreSelections.includes(id);return `<article class="selection-card ${selected?"selected":""}" data-id="${id}"><h2>${card.front} <span class="card-small-id">${id}</span></h2><p>선택 ${state.comparisonWins[id]}회 · 비교 ${state.comparisonCount[id]}회</p><button class="secondary-button pairwise-toggle" type="button">${selected?"유지":"후보로 교체"}</button>${deepReferenceHtml(card)}</article>`;}).join("");document.getElementById("pairwise-selection-count").textContent=`${state.coreSelections.length} / 3 선택`;document.querySelectorAll(".pairwise-toggle").forEach(button=>button.addEventListener("click",()=>{const id=button.closest(".selection-card").dataset.id,index=state.coreSelections.indexOf(id);if(index>=0)state.coreSelections.splice(index,1);else if(state.coreSelections.length<3)state.coreSelections.push(id);renderPairwiseResults();}));showScreen("pairwise-result");}
function renderAbsoluteConfirm(){state.absoluteCandidates.forEach(id=>{if(!state.absoluteConfirmResults[id])state.absoluteConfirmResults[id]="must";});document.getElementById("absolute-confirm-list").innerHTML=state.absoluteCandidates.map(id=>{const card=cardById(id),value=state.absoluteConfirmResults[id];return `<article class="result-group" data-id="${id}"><h2>${card.front} <span class="card-small-id">${id}</span></h2><p>${card.back}</p><div class="decision-buttons"><button type="button" data-value="must" class="${value==="must"?"selected":""}">그렇다</button><button type="button" data-value="nice" class="${value==="nice"?"selected":""}">중요하지만 조정 가능하다</button></div>${deepReferenceHtml(card)}</article>`;}).join("")||`<section class="result-group"><p>심층탐색 후 반드시 필요로 남은 조건은 없습니다.</p><p>이는 문제가 있는 결과가 아니라, 처음 생각했던 기준을 상담과정에서 다시 정리한 결과입니다.</p></section>`;document.querySelectorAll("#absolute-confirm-list .decision-buttons button").forEach(button=>button.addEventListener("click",()=>{state.absoluteConfirmResults[button.closest("article").dataset.id]=button.dataset.value;renderAbsoluteConfirm();}));showScreen("absolute-confirm");}
function confirmAbsolute(){state.absoluteConditions=state.absoluteCandidates.filter(id=>state.absoluteConfirmResults[id]==="must").slice(0,3);state.absoluteCandidates.filter(id=>!state.absoluteConditions.includes(id)).forEach(id=>state.quickReviewResults[id]="nice");renderImportantSelection();}
function getImportantCandidates(){const adjusted=state.postDeepMustCards.filter(id=>!state.absoluteConditions.includes(id)&&state.answers[id]!=="low");const preferred=JOB_CARDS.filter(card=>state.answers[card.id]==="nice"&&!state.absoluteConditions.includes(card.id)).map(card=>card.id);return [...new Set([...adjusted,...preferred])];}
function renderImportantSelection(){const candidates=getImportantCandidates();state.importantConditions=state.importantConditions.filter(id=>candidates.includes(id)).slice(0,5);document.getElementById("important-list").innerHTML=candidates.map(id=>{const card=cardById(id),selected=state.importantConditions.includes(id);return `<article class="selection-card ${selected?"selected":""}" data-id="${id}"><h2>${card.front} <span class="card-small-id">${id}</span></h2><p>${card.back}</p><button class="secondary-button important-toggle" type="button">${selected?"선택됨":"선택"}</button>${deepReferenceHtml(card)}</article>`;}).join("")||`<section class="result-group"><p>현재 중요조건 후보가 없습니다. 중요조건은 0개로 확정할 수 있습니다.</p></section>`;document.getElementById("important-selection-count").textContent=`${state.importantConditions.length} / 5 선택`;document.querySelectorAll(".important-toggle").forEach(button=>button.addEventListener("click",()=>{const id=button.closest(".selection-card").dataset.id,index=state.importantConditions.indexOf(id);if(index>=0)state.importantConditions.splice(index,1);else if(state.importantConditions.length<5)state.importantConditions.push(id);renderImportantSelection();}));showScreen("important");}
function finalizeConditions(){const absolute=new Set(state.absoluteConditions),important=new Set(state.importantConditions);state.preferredConditions=[];state.unimportantConditions=[];state.finalClassifications={};state.criteriaHistory={};JOB_CARDS.forEach(card=>{let final;if(absolute.has(card.id))final="absolute";else if(important.has(card.id))final="important";else if(state.answers[card.id]==="low")final="unimportant";else final="preferred";state.finalClassifications[card.id]=final;if(final==="preferred")state.preferredConditions.push(card.id);if(final==="unimportant")state.unimportantConditions.push(card.id);const response=state.deepResponses[card.id];state.criteriaHistory[card.id]={initialClassification:response?.initialClassification||state.answers[card.id],postDeepClassification:response?.finalClassification||state.answers[card.id],finalClassification:final};});validateFinalConditions();saveState();renderFinalResults();}
function validateFinalConditions(){const groups=[state.absoluteConditions,state.importantConditions,state.preferredConditions,state.unimportantConditions],all=groups.flat();if(state.absoluteConditions.length>3||state.importantConditions.length>5||all.length!==60||new Set(all).size!==60)console.error("V0.3 최종 분류 오류: 네 범주는 중복 없이 총 60개여야 합니다.",{groups,total:all.length,unique:new Set(all).size});}
function conditionListHtml(ids){return ids.map(id=>`<li>${cardById(id).front}<span class="card-small-id">${id}</span></li>`).join("")||"<li>선택된 조건이 없습니다.</li>";}
function renderFinalResults(){validateFinalConditions();document.getElementById("classification-journey").textContent=`처음 반드시 필요 ${state.deepCardIds.length}개 → 심층탐색 후 ${state.postDeepMustCards.length}개 → 최종 절대조건 ${state.absoluteConditions.length}개`;document.getElementById("final-condition-groups").innerHTML=`<section class="result-group"><h2>절대조건 <span class="card-small-id">${state.absoluteConditions.length}개</span></h2><ul>${conditionListHtml(state.absoluteConditions)}</ul></section><section class="result-group"><h2>중요조건 <span class="card-small-id">${state.importantConditions.length}개</span></h2><ul>${conditionListHtml(state.importantConditions)}</ul></section><section class="result-group"><details><summary><strong>선호조건 ${state.preferredConditions.length}개</strong></summary><ul>${conditionListHtml(state.preferredConditions)}</ul></details></section><section class="result-group"><details><summary><strong>중요하지 않은 조건 ${state.unimportantConditions.length}개</strong></summary><ul>${conditionListHtml(state.unimportantConditions)}</ul></details></section>`;showScreen("final");}

const assessmentItems=[
  {key:"importance",label:"① 중요도",question:"이 조건은 나에게 얼마나 중요한가요?",low:"전혀 중요하지 않음",high:"반드시 지키고 싶을 만큼 매우 중요함"},
  {key:"reality",label:"② 현실성",question:"현재 상황에서 이 조건을 충족하는 직업을 얻을 가능성은 어느 정도라고 생각하나요?",low:"현재는 거의 어렵다고 느낌",high:"충분히 가능하다고 느낌"},
  {key:"readiness",label:"③ 준비도",question:"이 조건을 가진 직업을 얻기 위한 역량·경험·자격 등이 얼마나 준비되어 있다고 생각하나요?",low:"거의 준비되지 않음",high:"충분히 준비되어 있음"},
  {key:"flexibility",label:"④ 유연성",question:"필요하다면 이 조건을 어느 정도 조정할 수 있나요?",low:"거의 조정할 수 없음",high:"상황에 따라 충분히 조정 가능"}
];
function getRealityTargets(){return [...state.absoluteConditions,...state.importantConditions].slice(0,8);}
function renderRealityIntro(){state.realityTargetIds=getRealityTargets();document.getElementById("reality-target-count").textContent=`${state.realityTargetIds.length}개`;showScreen("reality-intro");}
function isAssessmentComplete(assessment){return assessmentItems.every(item=>Number.isInteger(assessment?.[item.key]));}
function renderRealityCard(){const ids=state.realityTargetIds.length?state.realityTargetIds:getRealityTargets();state.realityTargetIds=ids;if(!ids.length){calculateCounselingAnalysis();renderRealityResults();return;}state.realityIndex=Math.max(0,Math.min(state.realityIndex,ids.length-1));const id=ids[state.realityIndex],card=cardById(id),assessment=state.realityAssessments[id]||{},position=state.realityIndex+1,type=state.absoluteConditions.includes(id)?"절대조건":"중요조건";document.getElementById("reality-progress-text").textContent=`현실검증 ${position} / ${ids.length}`;document.getElementById("reality-progress-bar").style.width=`${position/ids.length*100}%`;document.getElementById("reality-card-category").textContent=card.category;document.getElementById("reality-card-id").textContent=card.id;document.getElementById("reality-card-type").textContent=`[${type}]`;document.getElementById("reality-card-name").textContent=card.cardName;document.getElementById("reality-card-front").textContent=card.front;document.getElementById("reality-card-back").textContent=card.back;document.getElementById("assessment-sliders").innerHTML=assessmentItems.map(item=>{const entered=Number.isInteger(assessment[item.key]),value=entered?assessment[item.key]:5;return `<div class="assessment-item ${entered?"":"untouched"}" data-key="${item.key}"><div class="assessment-heading"><strong>${item.label}</strong><span class="assessment-value">${entered?value:"미입력"}</span></div><p class="assessment-question">${item.question}</p><input type="range" min="0" max="10" step="1" value="${value}" aria-label="${item.label} 점수"><div class="assessment-range"><span>0 = ${item.low}</span><span>10 = ${item.high}</span></div></div>`;}).join("");document.querySelectorAll(".assessment-item input").forEach(input=>input.addEventListener("input",()=>{const item=input.closest(".assessment-item"),key=item.dataset.key;if(!state.realityAssessments[id])state.realityAssessments[id]={};state.realityAssessments[id][key]=Number(input.value);item.classList.remove("untouched");item.querySelector(".assessment-value").textContent=input.value;document.getElementById("reality-next-button").disabled=!isAssessmentComplete(state.realityAssessments[id]);saveState();}));document.getElementById("reality-previous-button").disabled=state.realityIndex===0;document.getElementById("reality-next-button").disabled=!isAssessmentComplete(assessment);document.getElementById("reality-next-button").textContent=position===ids.length?"결과 확인 →":"다음 조건 →";showScreen("reality");}
function moveRealityNext(){if(!isAssessmentComplete(state.realityAssessments[state.realityTargetIds[state.realityIndex]]))return;if(state.realityIndex<state.realityTargetIds.length-1){state.realityIndex++;renderRealityCard();}else{calculateCounselingAnalysis();renderRealityResults();}}
function readinessBranch(score){if(score<=counselingSettings.readinessLowMax)return{label:"역량개발 탐색",questions:["이 조건을 가진 직업을 얻기 위해 현재 가장 부족하다고 느끼는 역량이나 경험은 무엇인가요?","교육·자격·실무경험 중 가장 먼저 준비할 수 있는 것은 무엇인가요?"]};if(score<=counselingSettings.readinessMediumMax)return{label:"준비와 구직탐색 병행",questions:["현재 바로 활용할 수 있는 역량과 추가로 준비해야 할 부분을 나누어 본다면 어떻게 될까요?","완벽하게 준비될 때까지 기다리지 않고 지금 탐색하거나 지원할 수 있는 범위는 어디까지일까요?"]};return{label:"노동시장·지원전략 탐색",questions:["준비는 충분하다고 생각하는데 현실성이 낮다고 본 이유는 무엇인가요?","지역·기업규모·고용형태·직무범위를 조금 넓히면 기회가 달라질까요?"]};}
function calculateCounselingAnalysis(){const targetSet=new Set(state.realityTargetIds),absoluteSet=new Set(state.absoluteConditions);state.realityGapSignals=[];state.rigiditySignals=[];state.sourceConcentrationSignals=[];state.cardCombinationSignals=[];state.counselingSignals=[];state.realityTargetIds.forEach(id=>{const assessment=state.realityAssessments[id];if(!isAssessmentComplete(assessment))return;const gap=assessment.importance-assessment.reality;if(gap>=counselingSettings.realityGapThreshold){const branch=readinessBranch(assessment.readiness);state.realityGapSignals.push({type:"gap",label:"현실성 차이 확인",cardId:id,gap,branch:branch.label,questions:branch.questions,importance:assessment.importance,reality:assessment.reality,readiness:assessment.readiness,priority:(absoluteSet.has(id)?3:2)+(gap>=5?3:2)+(assessment.importance>=9?2:0)});}if(assessment.importance>=counselingSettings.highImportanceThreshold&&assessment.flexibility<=counselingSettings.lowFlexibilityThreshold)state.rigiditySignals.push({type:"rigidity",label:"조정하기 어려운 핵심기준",cardId:id,importance:assessment.importance,flexibility:assessment.flexibility,question:"이 조건을 조정하기 어려운 가장 큰 이유는 무엇인가요?",priority:(absoluteSet.has(id)?3:2)+(assessment.importance>=9?2:0)+(assessment.flexibility<=2?2:0)});});state.realityGapSignals.sort((a,b)=>b.gap-a.gap||(absoluteSet.has(b.cardId)?1:0)-(absoluteSet.has(a.cardId)?1:0)||b.importance-a.importance);const sourceCards=state.deepCardIds.filter(id=>(state.deepResponses[id]?.selectedSources||[]).length);counselingSources.forEach(source=>{if(!sourceCards.length)return;const count=sourceCards.filter(id=>state.deepResponses[id].selectedSources.includes(source.id)).length,ratio=count/sourceCards.length;if(ratio>=counselingSettings.sourceConcentrationThreshold)state.sourceConcentrationSignals.push({type:"source",label:`주요 기준출처: ${source.label}`,sourceId:source.id,count,total:sourceCards.length,ratio,question:sourceExplorationQuestions[source.id]||"",warning:!["S1","S2"].includes(source.id),priority:2});});cardCombinationRules.forEach(rule=>{if(rule.cards.every(id=>targetSet.has(id)))state.cardCombinationSignals.push({type:"combination",label:rule.type==="clarify"?"조건 구체화":"우선순위 확인",cards:rule.cards,question:rule.question,priority:1});});if(state.postDeepMustCards.length>=counselingSettings.mustHaveExcessThreshold)state.counselingSignals.push({type:"process",label:"핵심조건 우선순위 확인",description:"심층탐색 후에도 반드시 필요하다고 남은 조건이 여러 개였습니다. 실제 직업선택에서 무엇을 우선할지 확인한 과정이 필요합니다."});state.counselingSignals.push(...state.realityGapSignals,...state.rigiditySignals,...state.sourceConcentrationSignals,...state.cardCombinationSignals);state.recommendedQuestions=selectRecommendedQuestions();saveState();}
function selectRecommendedQuestions(){const candidates=[];if(state.realityGapSignals[0])candidates.push({key:`gap-${state.realityGapSignals[0].cardId}`,source:"현실성",text:state.realityGapSignals[0].questions[0],priority:state.realityGapSignals[0].priority});if(state.rigiditySignals[0])candidates.push({key:`rigidity-${state.rigiditySignals[0].cardId}`,source:"유연성",text:state.rigiditySignals[0].question,priority:state.rigiditySignals[0].priority});const source=state.sourceConcentrationSignals.find(signal=>signal.warning&&signal.question);if(source)candidates.push({key:`source-${source.sourceId}`,source:"기준출처",text:source.question,priority:source.priority});if(state.cardCombinationSignals[0])candidates.push({key:`combination-${state.cardCombinationSignals[0].cards.join("-")}`,source:state.cardCombinationSignals[0].label,text:state.cardCombinationSignals[0].question,priority:state.cardCombinationSignals[0].priority});const unique=[...new Map(candidates.sort((a,b)=>b.priority-a.priority).map(item=>[item.text,item])).values()].slice(0,counselingSettings.maxRecommendedQuestions);return unique.length?unique:[{key:"default",source:"핵심기준",text:"오늘 정리한 핵심조건 중 실제 직업을 선택할 때 가장 지키고 싶은 것은 무엇인가요?",priority:0}];}
function renderRealityResults(){calculateCounselingAnalysis();const names=ids=>ids.map(id=>cardById(id).front).join(" · ")||"선택된 조건 없음";document.getElementById("reality-core-summary").innerHTML=`<div class="count-item">절대조건<strong>${state.absoluteConditions.length}개</strong><span class="summary-names">${names(state.absoluteConditions)}</span></div><div class="count-item">중요조건<strong>${state.importantConditions.length}개</strong><span class="summary-names">${names(state.importantConditions)}</span></div>`;document.getElementById("assessment-table-body").innerHTML=state.realityTargetIds.map(id=>{const card=cardById(id),a=state.realityAssessments[id],type=state.absoluteConditions.includes(id)?"절대":"중요";return `<tr><td data-label="조건">${card.cardName}</td><td data-label="구분">${type}</td><td data-label="중요도">${a.importance}</td><td data-label="현실성">${a.reality}</td><td data-label="준비도">${a.readiness}</td><td data-label="유연성">${a.flexibility}</td></tr>`;}).join("");document.getElementById("signal-list").innerHTML=state.counselingSignals.map(signal=>signalHtml(signal)).join("")||`<p>현재 점수에서 별도의 추가탐색 신호는 나타나지 않았습니다.</p>`;renderRecommendedQuestions();showScreen("reality-result");}
function signalHtml(signal){if(signal.type==="process")return`<article class="signal-item"><h3>${signal.label}</h3><p>${signal.description}</p></article>`;if(signal.type==="gap"){const card=cardById(signal.cardId);return`<article class="signal-item"><h3>${signal.label}</h3><p class="signal-detail">${card.cardName} — 중요도 ${signal.importance} / 현실성 ${signal.reality} / Gap ${signal.gap}</p><p>준비도 ${signal.readiness} → ${signal.branch} 권장</p><p>중요하게 생각하는 정도에 비해 현재 실현 가능성은 낮게 평가했습니다.</p></article>`;}if(signal.type==="rigidity"){const card=cardById(signal.cardId);return`<article class="signal-item"><h3>${signal.label}</h3><p>${card.cardName} — 중요도 ${signal.importance} / 유연성 ${signal.flexibility}</p><p>매우 중요하게 생각하면서 상황에 따라 조정하기는 어렵다고 평가한 조건입니다.</p></article>`;}if(signal.type==="source")return`<article class="signal-item"><h3>${signal.label}</h3><p>응답한 심층탐색 카드 ${signal.total}개 중 ${signal.count}개 (${Math.round(signal.ratio*100)}%)</p></article>`;return`<article class="signal-item"><h3>${signal.label}</h3><p>${signal.cards.map(id=>cardById(id).cardName).join(" + ")}</p></article>`;}
function renderRecommendedQuestions(){document.getElementById("recommended-question-list").innerHTML=state.recommendedQuestions.map(question=>{const saved=state.counselorQuestionNotes[question.key]||{useStatus:"",note:""};return`<article class="recommended-question" data-key="${question.key}"><span class="question-source">[${question.source}]</span><p>${question.text}</p><div class="question-actions"><button type="button" data-value="use" class="${saved.useStatus==="use"?"selected":""}">상담에 사용</button><button type="button" data-value="skip" class="${saved.useStatus==="skip"?"selected":""}">건너뛰기</button></div><textarea class="question-note" placeholder="상담 메모 (선택)">${escapeHtml(saved.note)}</textarea></article>`;}).join("");document.querySelectorAll(".recommended-question").forEach(element=>{const key=element.dataset.key;if(!state.counselorQuestionNotes[key])state.counselorQuestionNotes[key]={useStatus:"",note:""};element.querySelectorAll(".question-actions button").forEach(button=>button.addEventListener("click",()=>{state.counselorQuestionNotes[key].useStatus=button.dataset.value;saveState();renderRecommendedQuestions();}));element.querySelector(".question-note").addEventListener("input",event=>{state.counselorQuestionNotes[key].note=event.target.value;saveState();});});}

const statementValidationOptions=["매우 그렇다","대체로 그렇다","수정하고 싶다","많이 다르다"];
const doingActivityOptions=["채용공고 검색","직업정보 탐색","교육·훈련","자격증 준비","실무경험 쌓기","이력서·자기소개서 작성","기업 지원","면접 준비","상담·정보수집","아직 특별히 하고 있는 것이 없음","기타"];
const evaluationOptions=["매우 도움이 된다","어느 정도 도움이 된다","부족한 부분이 있다","잘 모르겠다"];
const commonImprovementAreas=["직무지식","실무경험","디지털 활용","자격·면허","문서·사무능력","의사소통","고객응대","문제해결","외국어","채용정보 탐색","취업서류","면접","지원전략","기타"];
const competencyMethods=["","교육","자격증","실무연습","현장경험","온라인학습","상담·정보탐색","기타"];
const actionTypes=["","채용공고 찾기","직업정보 조사","교육·훈련 찾기","자격 준비","실무경험 찾기","이력서·자기소개서 수정","기업 지원","면접 준비","상담·정보수집","기타"];
function careerPhrase(card){const text=card.front;if(card.id==="E01")return"서로 원만하게 협력할 수 있는 분위기에서";if(card.id==="E02")return"서로 존중하는 분위기에서";if(card.id==="B01")return"안정적으로 오래 일하고";if(card.id==="B02")return"고용이 안정적인 직장에서";if(card.id==="C02")return"안정적인 소득을 얻고";if(card.id==="C03")return"경력에 맞는 보상을 받으며";if(card.id==="E12")return"일과 생활의 균형을 유지하며";if(card.id==="F04")return"직원의 성장을 지원하는 조직에서";if(card.category==="업무내용")return`‘${text}’을 할 수 있고`;if(card.category==="고용조건")return`‘${text}’ 조건으로 일하며`;if(card.category==="보상")return`‘${text}’ 보상을 중요하게 생각하고`;if(card.category==="근무환경")return`‘${text}’ 환경에서`;if(card.category==="심리적·관계적 조건")return`‘${text}’을 느낄 수 있고`;return`‘${text}’ 회사에서`;}
function generateCareerStatement(){const absolutePhrases=state.absoluteConditions.map(id=>careerPhrase(cardById(id))),importantPhrases=state.importantConditions.slice(0,2).map(id=>careerPhrase(cardById(id)));if(!absolutePhrases.length&&!importantPhrases.length)return"나는 현재 나에게 맞는 직업선택 기준을 계속 탐색하고 확인해 가고 싶습니다.";const build=phrases=>`나는 ${phrases.join(", ")} 나의 핵심기준을 존중할 수 있는 직장을 원합니다.`;let supporting=[...importantPhrases],statement=build([...absolutePhrases,...supporting]);while(statement.length>110&&supporting.length){supporting.pop();statement=build([...absolutePhrases,...supporting]);}return statement;}
function renderStatementScreen(){state.generatedCareerStatement=generateCareerStatement();if(!state.clientApprovedCareerStatement)state.clientApprovedCareerStatement=state.generatedCareerStatement;document.getElementById("generated-statement").textContent=state.generatedCareerStatement;document.getElementById("approved-statement").value=state.clientApprovedCareerStatement;document.getElementById("statement-validation-options").innerHTML=statementValidationOptions.map(option=>`<button type="button" data-value="${option}" class="${state.careerStatementValidation===option?"selected":""}">${option}</button>`).join("");document.querySelectorAll("#statement-validation-options button").forEach(button=>button.addEventListener("click",()=>{state.careerStatementValidation=button.dataset.value;saveState();renderStatementScreen();}));document.getElementById("approved-statement").addEventListener("input",event=>{state.clientApprovedCareerStatement=event.target.value;saveState();});showScreen("statement");}
function checkboxGridHtml(options,selected,className=""){return options.map(option=>{const value=typeof option==="string"?option:option.value,label=typeof option==="string"?option:option.label,checked=selected.includes(value);return`<label class="compact-check ${checked?"checked":""} ${className}"><input type="checkbox" value="${value}" ${checked?"checked":""}><span>${label}</span></label>`;}).join("");}
function getReadinessSuggestions(){const scores=getRealityTargets().map(id=>state.realityAssessments[id]?.readiness).filter(Number.isInteger),minimum=scores.length?Math.min(...scores):null;if(minimum!==null&&minimum<=4)return{guide:"현재는 역량이나 경험을 구체적으로 보완하는 계획을 세워볼 수 있습니다.",areas:["직무지식","자격·면허","실무경험","디지털 활용","기타"]};if(minimum!==null&&minimum<=7)return{guide:"현재 가지고 있는 역량을 활용하면서 추가로 준비할 부분을 함께 생각해 볼 수 있습니다.",areas:["실무보완","추가교육","직업정보 탐색","실제 지원",...commonImprovementAreas]};if(minimum!==null)return{guide:"준비도는 비교적 높게 평가했습니다. 역량개발뿐 아니라 실제 채용시장과 지원범위를 살펴볼 필요가 있습니다.",areas:["채용공고 탐색","지원기업 확대","근무지역 조정","기업규모 조정","고용형태 조정","지원직무 범위 확대","이력서·면접전략",...commonImprovementAreas]};return{guide:"현재 상황에서 보완하면 도움이 될 영역을 직접 선택해 주세요.",areas:commonImprovementAreas};}
function syncConditionsFromW(){const original=state.wdepOriginalAbsoluteConditions,maintained=new Set(state.maintainedConditions),removed=original.filter(id=>!maintained.has(id));state.absoluteConditions=[...state.maintainedConditions].slice(0,3);removed.forEach(id=>{if(!state.importantConditions.includes(id)&&state.importantConditions.length<5)state.importantConditions.push(id);});state.importantConditions=state.importantConditions.filter(id=>!maintained.has(id));const absolute=new Set(state.absoluteConditions),important=new Set(state.importantConditions);state.preferredConditions=[];state.unimportantConditions=[];JOB_CARDS.forEach(card=>{let final=absolute.has(card.id)?"absolute":important.has(card.id)?"important":state.answers[card.id]==="low"?"unimportant":"preferred";state.finalClassifications[card.id]=final;if(final==="preferred")state.preferredConditions.push(card.id);if(final==="unimportant")state.unimportantConditions.push(card.id);if(state.criteriaHistory[card.id])state.criteriaHistory[card.id].finalClassification=final;});state.realityTargetIds=getRealityTargets();calculateCounselingAnalysis();state.generatedCareerStatement=generateCareerStatement();document.getElementById("condition-change-notice").hidden=false;saveState();}
function bindCheckboxes(containerSelector,selectedArray,onChange,max=Infinity){document.querySelectorAll(`${containerSelector} input[type="checkbox"]`).forEach(input=>input.addEventListener("change",()=>{const index=selectedArray.indexOf(input.value);if(input.checked&&index<0){if(selectedArray.length>=max){input.checked=false;return;}selectedArray.push(input.value);}else if(!input.checked&&index>=0)selectedArray.splice(index,1);onChange();}));}
function updateCompetencies(){state.competenciesToDevelop=state.wdep.improvementAreas.map(category=>state.competenciesToDevelop.find(item=>item.category===category)||{category,detail:"",method:""});}
function generateActionSentence(){const plan=state.actionPlan;if(!plan.what||!plan.amount||!plan.deadline)return"무엇을, 어느 정도, 언제까지 할지 입력하면 실행문장이 만들어집니다.";const [year,month,day]=plan.deadline.split("-").map(Number),base=plan.what.trim();if(/확인$/.test(base))return`${month}월 ${day}일까지 ${base.replace(/\s*확인$/,"")} ${plan.amount}를 확인한다.`;return`${month}월 ${day}일까지 ${base} ${plan.amount}를 실행한다.`;}
function renderWdepScreen(){if(!state.wdepOriginalAbsoluteConditions.length)state.wdepOriginalAbsoluteConditions=[...state.absoluteConditions];if(!state.maintainedConditions.length&&state.wdep.wantConfirmed!=="조정하고 싶다")state.maintainedConditions=[...state.absoluteConditions];document.getElementById("wdep-reference-questions").innerHTML=state.recommendedQuestions.slice(0,3).map(question=>`<li>${question.text}</li>`).join("")||"<li>저장된 참고 질문이 없습니다.</li>";document.getElementById("want-options").innerHTML=["그렇다","조정하고 싶다"].map(value=>`<button type="button" data-value="${value}" class="${state.wdep.wantConfirmed===value?"selected":""}">${value}</button>`).join("");document.getElementById("want-condition-list").innerHTML=checkboxGridHtml(state.wdepOriginalAbsoluteConditions.map(id=>({value:id,label:cardById(id).front})),state.maintainedConditions);document.getElementById("doing-options").innerHTML=checkboxGridHtml(doingActivityOptions,state.wdep.doingActivities);document.getElementById("doing-other-wrap").hidden=!state.wdep.doingActivities.includes("기타");document.getElementById("doing-other").value=state.wdep.doingOther;document.getElementById("doing-note").value=state.wdep.doingNote;document.getElementById("evaluation-options").innerHTML=evaluationOptions.map(value=>`<button type="button" data-value="${value}" class="${state.wdep.evaluation===value?"selected":""}">${value}</button>`).join("");const suggestions=getReadinessSuggestions();document.getElementById("readiness-guidance").textContent=suggestions.guide;const areas=[...new Set(suggestions.areas)];document.getElementById("improvement-options").innerHTML=checkboxGridHtml(areas,state.wdep.improvementAreas);document.getElementById("improvement-count").textContent=`${state.wdep.improvementAreas.length} / 3 선택`;document.getElementById("maintained-condition-list").innerHTML=checkboxGridHtml(state.wdepOriginalAbsoluteConditions.map(id=>({value:id,label:cardById(id).front})),state.maintainedConditions);const adjustableCandidates=[...new Set([...state.importantConditions,...state.preferredConditions])];document.getElementById("adjustable-condition-list").innerHTML=checkboxGridHtml(adjustableCandidates.map(id=>({value:id,label:cardById(id).front})),state.adjustableConditions);updateCompetencies();document.getElementById("competency-detail-list").innerHTML=state.competenciesToDevelop.map((item,index)=>`<article class="competency-item" data-index="${index}"><h4>${item.category}</h4><label>구체적으로 개발할 것<input class="competency-detail" value="${escapeHtml(item.detail)}"></label><label>준비방법<select class="competency-method">${competencyMethods.map(method=>`<option value="${method}" ${item.method===method?"selected":""}>${method||"선택해 주세요"}</option>`).join("")}</select></label></article>`).join("")||"<p>앞에서 보완영역을 선택하면 여기에 표시됩니다.</p>";document.getElementById("action-type").innerHTML=actionTypes.map(value=>`<option value="${value}" ${state.actionPlan.actionType===value?"selected":""}>${value||"선택해 주세요"}</option>`).join("");document.getElementById("action-what").value=state.actionPlan.what;document.getElementById("action-amount").value=state.actionPlan.amount;document.getElementById("action-deadline").value=state.actionPlan.deadline;state.actionPlan.generatedSentence=generateActionSentence();document.getElementById("generated-action-sentence").textContent=state.actionPlan.generatedSentence;document.getElementById("feasibility-options").innerHTML=["충분히 가능하다","조금 조정하면 가능하다","다시 정하고 싶다"].map(value=>`<button type="button" data-value="${value}" class="${state.actionPlan.feasibility===value?"selected":""}">${value}</button>`).join("");document.querySelectorAll("#want-options button").forEach(button=>button.addEventListener("click",()=>{state.wdep.wantConfirmed=button.dataset.value;if(button.dataset.value==="그렇다")state.maintainedConditions=[...state.wdepOriginalAbsoluteConditions];syncConditionsFromW();renderWdepScreen();}));bindCheckboxes("#want-condition-list",state.maintainedConditions,()=>{state.wdep.wantConfirmed="조정하고 싶다";syncConditionsFromW();renderWdepScreen();},3);bindCheckboxes("#maintained-condition-list",state.maintainedConditions,()=>{state.wdep.wantConfirmed="조정하고 싶다";syncConditionsFromW();renderWdepScreen();},3);bindCheckboxes("#doing-options",state.wdep.doingActivities,()=>{saveState();renderWdepScreen();});bindCheckboxes("#improvement-options",state.wdep.improvementAreas,()=>{updateCompetencies();saveState();renderWdepScreen();},3);bindCheckboxes("#adjustable-condition-list",state.adjustableConditions,()=>{saveState();renderWdepScreen();});document.querySelectorAll("#evaluation-options button").forEach(button=>button.addEventListener("click",()=>{state.wdep.evaluation=button.dataset.value;saveState();renderWdepScreen();}));document.getElementById("doing-other").addEventListener("input",event=>{state.wdep.doingOther=event.target.value;saveState();});document.getElementById("doing-note").addEventListener("input",event=>{state.wdep.doingNote=event.target.value;saveState();});document.querySelectorAll(".competency-item").forEach(element=>{const item=state.competenciesToDevelop[Number(element.dataset.index)];element.querySelector(".competency-detail").addEventListener("input",event=>{item.detail=event.target.value;saveState();});element.querySelector(".competency-method").addEventListener("change",event=>{item.method=event.target.value;saveState();});});["action-type","action-what","action-amount","action-deadline"].forEach(id=>document.getElementById(id).addEventListener("input",event=>{const key={"action-type":"actionType","action-what":"what","action-amount":"amount","action-deadline":"deadline"}[id];state.actionPlan[key]=event.target.value;state.actionPlan.confirmed=false;state.actionPlan.generatedSentence=generateActionSentence();document.getElementById("generated-action-sentence").textContent=state.actionPlan.generatedSentence;saveState();}));document.querySelectorAll("#feasibility-options button").forEach(button=>button.addEventListener("click",()=>{state.actionPlan.feasibility=button.dataset.value;saveState();renderWdepScreen();}));showScreen("wdep");}
function confirmActionPlan(){state.actionPlan.generatedSentence=generateActionSentence();if(!state.actionPlan.what||!state.actionPlan.amount||!state.actionPlan.deadline)return;state.actionPlan.confirmed=true;state.confirmedActionPlan=state.actionPlan.generatedSentence;saveState();document.getElementById("confirm-action-button").textContent="실행계획이 확정되었습니다";}
function renderCounselingSummary(){const names=ids=>ids.map(id=>cardById(id)?.front).filter(Boolean).join(" · ")||"선택된 조건 없음",competencies=state.competenciesToDevelop.map(item=>`${item.category}${item.detail?` — ${item.detail}`:""}`).join("\n")||"선택된 영역 없음";document.getElementById("counseling-summary-content").innerHTML=`<section class="result-group"><h2>① 내가 원하는 직업</h2><p class="summary-value">${escapeHtml(state.clientApprovedCareerStatement||state.generatedCareerStatement)}</p></section><section class="result-group"><h2>② 계속 유지할 조건</h2><p class="summary-value">${names(state.maintainedConditions)}</p></section><section class="result-group"><h2>③ 중요하지만 조정 가능한 조건</h2><p class="summary-value">${names(state.adjustableConditions)}</p></section><section class="result-group"><h2>④ 개발하거나 보완할 부분</h2><p class="summary-value">${escapeHtml(competencies)}</p></section><section class="result-group"><h2>⑤ 이번에 실행할 행동</h2><p class="career-statement">${escapeHtml(state.confirmedActionPlan||state.actionPlan.generatedSentence||"아직 확정된 행동이 없습니다.")}</p></section>`;document.getElementById("next-check-point").value=state.nextCheckPoint;document.getElementById("next-check-point").addEventListener("input",event=>{state.nextCheckPoint=event.target.value;saveState();});showScreen("counseling-summary");}

const domainDefinitions=[
  {prefix:"A",label:"일의 내용",total:24},{prefix:"B",label:"고용·근무 안정",total:6},{prefix:"C",label:"보상",total:6},
  {prefix:"D",label:"근무환경",total:6},{prefix:"E",label:"조직문화·관계",total:12},{prefix:"F",label:"성장·전망",total:6}
];
function getLatestClassification(cardId,classifications=state.finalClassifications){if(classifications&&classifications!==state.finalClassifications&&classifications[cardId])return classifications[cardId];if(state.absoluteConditions.includes(cardId))return"absolute";if(state.importantConditions.includes(cardId))return"important";if(state.preferredConditions.includes(cardId))return"preferred";if(state.unimportantConditions.includes(cardId))return"unimportant";return classifications[cardId]||({must:"absolute",nice:"preferred",low:"unimportant"}[state.answers[cardId]])||"unimportant";}
function calculateDomainScores(cards,classifications){const weights={absolute:2,important:1,preferred:1,unimportant:0};return domainDefinitions.map(domain=>{const domainCards=cards.filter(card=>card.id.startsWith(domain.prefix)),score=domainCards.reduce((sum,card)=>sum+(weights[getLatestClassification(card.id,classifications)]||0),0),percentage=Math.max(0,Math.min(100,Math.round(score/(domain.total*2)*100)));return{...domain,score,percentage};});}
function finalNamesHtml(ids){return ids.length?`<ul>${ids.map(id=>`<li>${escapeHtml(cardById(id)?.front||id)} <span class="card-small-id">${id}</span></li>`).join("")}</ul>`:"<p class=\"empty-result\">정리된 항목이 없습니다.</p>";}
function selectFinalInsights(){const absolute=new Set(state.absoluteConditions),important=new Set(state.importantConditions),items=[];const gaps=[...state.realityGapSignals].sort((a,b)=>b.gap-a.gap);gaps.filter(item=>absolute.has(item.cardId)).forEach(item=>items.push({rank:1,title:`${cardById(item.cardId)?.front||item.cardId}: 중요도와 현실성 차이`,detail:`중요도 ${item.importance}점 · 현실성 ${item.reality}점 · 차이 ${item.gap}점. ${item.branch||"현재 가능한 준비 단계를 함께 확인해 보세요."}`}));state.rigiditySignals.filter(item=>absolute.has(item.cardId)).forEach(item=>items.push({rank:2,title:`${cardById(item.cardId)?.front||item.cardId}: 조정 범위 확인`,detail:`중요도 ${item.importance}점 · 유연성 ${item.flexibility}점. 지키고 싶은 핵심과 조정 가능한 범위를 구분해 보세요.`}));gaps.filter(item=>important.has(item.cardId)).forEach(item=>items.push({rank:3,title:`${cardById(item.cardId)?.front||item.cardId}: 현실성 차이`,detail:`중요도 ${item.importance}점 · 현실성 ${item.reality}점 · 차이 ${item.gap}점. 실현 가능성을 높일 다음 행동을 살펴보세요.`}));state.realityTargetIds.forEach(id=>{const value=state.realityAssessments[id];if(value&&isAssessmentComplete(value)&&(value.readiness<=counselingSettings.readinessLowMax||value.reality<=3))items.push({rank:4,title:`${cardById(id)?.front||id}: 준비 상황 확인`,detail:`현실성 ${value.reality}점 · 준비도 ${value.readiness}점. 현재 할 수 있는 작은 준비부터 구체화해 보세요.`});});[...state.sourceConcentrationSignals,...state.cardCombinationSignals].forEach(item=>items.push({rank:5,title:item.label,detail:item.question||item.description||"이 기준이 현재 직업선택에 주는 의미를 함께 확인해 보세요."}));return items.sort((a,b)=>a.rank-b.rank).filter((item,index,array)=>array.findIndex(other=>other.title===item.title)===index).slice(0,2);}
function deepDetailHtml(){const rows=state.deepCardIds.map(id=>{const response=state.deepResponses[id]||{},sources=(response.selectedSources||[]).map(sourceId=>counselingSources.find(source=>source.id===sourceId)?.label||sourceId).join(" · ")||"선택 없음";return`<article class="detail-record"><h4>${escapeHtml(cardById(id)?.front||id)} <span class="card-small-id">${id}</span></h4><p><strong>질문 1:</strong> ${escapeHtml(response.question1Answer||"기록 없음")}</p><p><strong>질문 2:</strong> ${escapeHtml(response.question2Answer||"기록 없음")}</p><p><strong>기준출처:</strong> ${escapeHtml(sources)}</p>${response.reclassificationNote?`<p><strong>변경 메모:</strong> ${escapeHtml(response.reclassificationNote)}</p>`:""}</article>`;});return rows.join("")||"<p>저장된 심층탐색 기록이 없습니다.</p>";}
function renderFinalResult(){const info=state.clientInfo||{},today=state.consultationCompletedAt?new Date(state.consultationCompletedAt):new Date(),statement=state.clientApprovedCareerStatement||state.generatedCareerStatement||"아직 정리된 직업선택 문장이 없습니다.",insights=selectFinalInsights(),scores=calculateDomainScores(JOB_CARDS,state.finalClassifications);document.getElementById("final-client-info").innerHTML=`<span><strong>상담일</strong>${today.toLocaleDateString("ko-KR")}</span><span><strong>이름/사례</strong>${escapeHtml(info.clientName||"미입력")}</span><span><strong>현재 상태</strong>${escapeHtml(info.currentStatus||"미입력")}</span>${info.desiredJobName?`<span><strong>희망직업</strong>${escapeHtml(info.desiredJobName)}</span>`:""}`;document.getElementById("final-career-statement").textContent=statement;document.getElementById("statement-fallback-note").hidden=Boolean(state.clientApprovedCareerStatement);document.getElementById("final-absolute-cards").innerHTML=finalNamesHtml(state.absoluteConditions);document.getElementById("final-important-cards").innerHTML=finalNamesHtml(state.importantConditions);document.getElementById("domain-score-chart").innerHTML=scores.map(item=>`<div class="domain-row"><span>${item.label}</span><div class="domain-track"><i style="width:${item.percentage}%"></i></div><strong>${item.percentage}</strong></div>`).join("");document.getElementById("final-reality-insights").innerHTML=insights.map(item=>`<article class="insight-item"><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.detail)}</p></article>`).join("")||"<p class=\"empty-result\">현재 표시할 현실검증 인사이트가 없습니다.</p>";document.getElementById("final-maintained").innerHTML=finalNamesHtml(state.maintainedConditions);document.getElementById("final-adjustable").innerHTML=finalNamesHtml(state.adjustableConditions);document.getElementById("final-competencies").innerHTML=state.competenciesToDevelop.length?`<ul>${state.competenciesToDevelop.map(item=>`<li>${escapeHtml(item.category)}${item.detail?` — ${escapeHtml(item.detail)}`:""}${item.method?` (${escapeHtml(item.method)})`:""}</li>`).join("")}</ul>`:"<p class=\"empty-result\">정리된 역량이 없습니다.</p>";document.getElementById("final-action").textContent=state.actionPlan.confirmed?(state.confirmedActionPlan||state.actionPlan.generatedSentence):"아직 확정된 행동계획이 없습니다.";document.getElementById("final-next-check").textContent=state.nextCheckPoint||"아직 정한 내용이 없습니다.";document.getElementById("final-process-summary").textContent=`처음 반드시 필요 ${state.deepCardIds.length}개 → 심층탐색 후 ${state.postDeepMustCards.length}개 → 최종 절대조건 ${state.absoluteConditions.length}개`;const classificationGroups=["absolute","important","preferred","unimportant"].map(type=>`<section><h3>${{absolute:"절대조건",important:"중요조건",preferred:"선호조건",unimportant:"중요하지 않은 조건"}[type]}</h3>${finalNamesHtml(JOB_CARDS.filter(card=>getLatestClassification(card.id)===type).map(card=>card.id))}</section>`).join("");const assessmentRows=state.realityTargetIds.map(id=>{const value=state.realityAssessments[id]||{};return`<tr><td>${escapeHtml(cardById(id)?.front||id)}</td><td>${value.importance??"-"}</td><td>${value.reality??"-"}</td><td>${value.readiness??"-"}</td><td>${value.flexibility??"-"}</td></tr>`;}).join("");document.getElementById("final-detail-content").innerHTML=`<h2>최종 60장 분류</h2>${classificationGroups}<h2>심층탐색 기록</h2>${deepDetailHtml()}<h2>TOP 선정 과정</h2><p>${escapeHtml(document.getElementById("final-process-summary").textContent)}</p><h2>현실검증 전체 점수</h2><div class="table-wrap"><table class="assessment-table"><thead><tr><th>조건</th><th>중요도</th><th>현실성</th><th>준비도</th><th>유연성</th></tr></thead><tbody>${assessmentRows||'<tr><td colspan="5">저장된 점수가 없습니다.</td></tr>'}</tbody></table></div><h2>WDEP 기록</h2><p><strong>W:</strong> ${escapeHtml(state.wdep.wantConfirmed||"기록 없음")}</p><p><strong>D:</strong> ${escapeHtml([...state.wdep.doingActivities,state.wdep.doingOther,state.wdep.doingNote].filter(Boolean).join(" · ")||"기록 없음")}</p><p><strong>E:</strong> ${escapeHtml([state.wdep.evaluation,...state.wdep.improvementAreas].filter(Boolean).join(" · ")||"기록 없음")}</p><p><strong>P:</strong> ${escapeHtml(state.confirmedActionPlan||state.actionPlan.generatedSentence||"기록 없음")}</p>`;document.getElementById("final-counselor-content").innerHTML=state.recommendedQuestions.slice(0,3).map(question=>{const note=state.counselorQuestionNotes[question.key]||{};return`<article class="detail-record"><h3>${escapeHtml(question.text)}</h3><p><strong>사용 여부:</strong> ${escapeHtml(note.useStatus||"미선택")}</p><p><strong>메모:</strong> ${escapeHtml(note.note||"기록 없음")}</p></article>`;}).join("")||"<p>저장된 상담자 질문이 없습니다.</p>";showScreen("final-result");}
function completeConsultation(){if(confirm("오늘 상담내용을 현재 기기에 저장한 상태로 상담을 완료하시겠습니까?")){state.counselingCompleted=true;state.consultationCompleted=true;state.consultationCompletedAt=new Date().toISOString();saveState();alert("상담내용이 현재 기기에 저장되었습니다.");renderFinalResult();}}
function resetConsultation(){if(confirm("현재 상담내용을 모두 초기화하고 새 상담을 시작하시겠습니까?")){localStorage.removeItem(STORAGE_KEY);state=createEmptyState();document.getElementById("start-form").reset();fillStartForm();showScreen("start");}}

function initialize(){try{validateData();loadState();fillStartForm();const completed=JOB_CARDS.every(card=>state.answers[card.id]);if(["deep","deep-result"].includes(state.screen)&&!state.deepCardIds.length)state.deepCardIds=getMustCards().map(card=>card.id);const advancedScreens=["core-select","pairwise","pairwise-result","absolute-confirm","important","final","reality-intro","reality","reality-result","reality-complete","statement","wdep","counseling-summary","final-result"];if(["result","deep-intro","deep","deep-result",...advancedScreens].includes(state.screen)&&!completed){showScreen("card");renderCard();}else if(state.screen==="result")renderResults();else if(state.screen==="deep-intro")renderDeepIntro();else if(state.screen==="deep")renderDeepCard();else if(state.screen==="deep-result")renderDeepResults();else if(state.screen==="core-select")renderCoreSelect();else if(state.screen==="pairwise")renderPairwise();else if(state.screen==="pairwise-result")renderPairwiseResults();else if(state.screen==="absolute-confirm")renderAbsoluteConfirm();else if(state.screen==="important")renderImportantSelection();else if(state.screen==="final")renderFinalResults();else if(state.screen==="reality-intro")renderRealityIntro();else if(state.screen==="reality")renderRealityCard();else if(state.screen==="reality-result")renderRealityResults();else if(state.screen==="reality-complete")showScreen("reality-complete");else if(state.screen==="statement")renderStatementScreen();else if(state.screen==="wdep")renderWdepScreen();else if(state.screen==="counseling-summary")renderCounselingSummary();else if(state.screen==="final-result")renderFinalResult();else if(state.screen==="card"&&Object.keys(state.clientInfo).length){showScreen("card");renderCard();}else showScreen("start");}catch(error){const box=document.getElementById("error-message");box.textContent=`앱을 불러오지 못했습니다: ${error.message}`;box.hidden=false;}}
document.getElementById("desired-job-status").addEventListener("change",updateDesiredJobInput);
document.getElementById("start-form").addEventListener("submit",event=>{event.preventDefault();state.clientInfo=Object.fromEntries(new FormData(event.currentTarget));state.currentIndex=0;showScreen("card");renderCard();});
document.getElementById("previous-button").addEventListener("click",()=>{if(state.currentIndex>0){state.currentIndex--;renderCard();}});
document.getElementById("edit-button").addEventListener("click",()=>{state.currentIndex=0;showScreen("card");renderCard();});
document.getElementById("deep-intro-button").addEventListener("click",renderDeepIntro);
document.getElementById("deep-intro-back").addEventListener("click",renderResults);
document.getElementById("deep-start-button").addEventListener("click",()=>{if(!state.deepCardIds.length)state.deepCardIds=getMustCards().map(card=>card.id);state.deepCardIds.forEach(id=>getDeepResponse(JOB_CARDS.find(card=>card.id===id)));updateFinalMustIds();state.deepIndex=0;renderDeepCard();});
document.getElementById("deep-previous-button").addEventListener("click",()=>{if(state.deepIndex>0){state.deepIndex--;renderDeepCard();}});
document.getElementById("deep-next-button").addEventListener("click",moveDeepNext);
document.getElementById("deep-edit-button").addEventListener("click",()=>{state.deepIndex=0;renderDeepCard();});
document.getElementById("back-to-result-button").addEventListener("click",renderResults);
document.getElementById("core-start-button").addEventListener("click",startCoreSelection);
document.getElementById("core-select-continue").addEventListener("click",continueCoreSelect);
document.getElementById("pairwise-confirm-button").addEventListener("click",()=>{state.absoluteCandidates=[...state.coreSelections];renderAbsoluteConfirm();});
document.getElementById("absolute-confirm-button").addEventListener("click",confirmAbsolute);
document.getElementById("important-confirm-button").addEventListener("click",finalizeConditions);
document.getElementById("reality-intro-button").addEventListener("click",renderRealityIntro);
document.getElementById("reality-start-button").addEventListener("click",()=>{state.realityTargetIds=getRealityTargets();state.realityIndex=0;renderRealityCard();});
document.getElementById("reality-previous-button").addEventListener("click",()=>{if(state.realityIndex>0){state.realityIndex--;renderRealityCard();}});
document.getElementById("reality-next-button").addEventListener("click",moveRealityNext);
document.getElementById("reality-edit-button").addEventListener("click",()=>{state.realityIndex=0;renderRealityCard();});
document.getElementById("reality-complete-button").addEventListener("click",()=>showScreen("reality-complete"));
document.getElementById("reality-future-button").addEventListener("click",renderStatementScreen);
document.getElementById("statement-continue-button").addEventListener("click",renderWdepScreen);
document.getElementById("confirm-action-button").addEventListener("click",confirmActionPlan);
document.getElementById("wdep-back-button").addEventListener("click",renderStatementScreen);
document.getElementById("wdep-complete-button").addEventListener("click",renderCounselingSummary);
document.getElementById("summary-back-button").addEventListener("click",renderWdepScreen);
document.getElementById("summary-edit-button").addEventListener("click",renderWdepScreen);
document.getElementById("counseling-complete-button").addEventListener("click",completeConsultation);
document.getElementById("final-result-button").addEventListener("click",renderFinalResult);
document.getElementById("final-core-edit-button").addEventListener("click",renderImportantSelection);
document.getElementById("final-reality-edit-button").addEventListener("click",()=>{state.realityIndex=0;renderRealityCard();});
["final-action-edit-button","action-edit-inline-button"].forEach(id=>document.getElementById(id).addEventListener("click",renderWdepScreen));
document.getElementById("final-complete-button").addEventListener("click",completeConsultation);
document.getElementById("final-reset-button").addEventListener("click",resetConsultation);
document.getElementById("reset-button").addEventListener("click",resetConsultation);
initialize();
